                .param("situacao", SituacaoAviso.LIDO.name())
                .param("id", id)
                .update();
        return jdbc.sql("SELECT * FROM aviso WHERE id = :id")
                .param("id", id)
                .query(AvisoRepositorio::mapear)
                .optional();
    }

    private static Aviso mapear(ResultSet rs, int linha) throws SQLException {
        return new Aviso(
